# ## Step 2 — The Scenario: Structured Consulting Recommendations
#
# You are a management consultant analyzing client problems. For each consulting brief (problem statement + context), you must produce a **structured recommendation** with exact fields: category (strategy/operations/finance), priority (high/medium/low), risk (identified risks as array), and control_measures (required actions as array).
#
# The challenge: the LLM returns free text. You need schema-validated JSON that your executive dashboard can parse and display reliably. Invalid JSON or missing fields crashes the pipeline.
#
# You'll build a validator that ensures the recommendation matches your schema, and retry with error feedback if it doesn't.

# %% [markdown]
# ## Step 3 — Define the JSON Schema
#
# Define the exact structure your recommendations must follow. Every field has a type, and some fields have constraints (enums for category/priority, required fields, arrays with specific item types).

# %%
recommendation_schema = {
    "type": "object",
    "properties": {
        "category": {
            "type": "string",
            "enum": ["strategy", "operations", "finance"]
        },
        "priority": {
            "type": "string",
            "enum": ["high", "medium", "low"]
        },
        "risk": {
            "type": "array",
            "items": {"type": "string"},
            "minItems": 1
        },
        "control_measures": {
            "type": "array",
            "items": {"type": "string"},
            "minItems": 1
        }
    },
    "required": ["category", "priority", "risk", "control_measures"]
}

print("Recommendation Schema:")
print(json.dumps(recommendation_schema, indent=2))

# %% [markdown]
# ## Step 4 — Build a Schema Validator
#
# Implement validation logic to check whether a parsed JSON object matches the schema. Validation catches three categories of errors: type mismatches, missing required fields, and constraint violations (enums, array length).

# %%
def validate_schema(data, schema):
    """Validate a Python object against a JSON Schema. Return list of error strings."""
    errors = []
    _validate(data, schema, "", errors)
    return errors

def _validate(data, schema, path, errors):
    schema_type = schema.get("type")
    
    if schema_type == "object":
        if not isinstance(data, dict):
            errors.append(f"{path}: expected object, got {type(data).__name__}")
            return
        for key in schema.get("required", []):
            if key not in data:
                errors.append(f"{path}.{key}: required field missing")
        properties = schema.get("properties", {})
        for key, value in data.items():
            if key in properties:
                _validate(value, properties[key], f"{path}.{key}", errors)
    
    elif schema_type == "array":
        if not isinstance(data, list):
            errors.append(f"{path}: expected array, got {type(data).__name__}")
            return
        min_items = schema.get("minItems", 0)
        if len(data) < min_items:
            errors.append(f"{path}: array has {len(data)} items, minimum is {min_items}")
        items_schema = schema.get("items", {})
        for i, item in enumerate(data):
            _validate(item, items_schema, f"{path}[{i}]", errors)
    
    elif schema_type == "string":
        if not isinstance(data, str):
            errors.append(f"{path}: expected string, got {type(data).__name__}")
            return
        enum_values = schema.get("enum")
        if enum_values and data not in enum_values:
            errors.append(f"{path}: '{data}' not in allowed values {enum_values}")

# Test the validator
valid_rec = {"category": "strategy", "priority": "high", "risk": ["market volatility"], "control_measures": ["diversify portfolio"]}
invalid_rec = {"category": "strategy", "priority": "urgent"}  # invalid enum, missing fields

print("Valid recommendation:", "PASS" if not validate_schema(valid_rec, recommendation_schema) else "FAIL")
print("Invalid recommendation:", "PASS (detected errors)" if validate_schema(invalid_rec, recommendation_schema) else "FAIL")
print("Errors:", validate_schema(invalid_rec, recommendation_schema))

