system_prompt = f"""You are a management consultant. Analyze this consulting brief and produce a JSON recommendation.
Your response MUST be valid JSON matching this schema:
{json.dumps(recommendation_schema)}

Respond ONLY with the JSON object, no markdown or extra text."""

r = await lrn_llm.call(
    [{"role": "user", "content": consulting_brief}],
    system=system_prompt,
    max_tokens=300
)
raw_response = lrn_llm.text(r)
print("LLM Response (raw):")
print(raw_response)

# %% [markdown]
# ## Step 6 — Parse and Validate the Response
#
# Attempt to parse the LLM's response as JSON, then validate it against the schema. If validation fails, log the errors.

# %%
try:
    parsed = json.loads(raw_response)
    print("✅ JSON parsed successfully")
except json.JSONDecodeError as e:
    print(f"❌ JSON parse error: {e}")
    parsed = None

if parsed:
    errors = validate_schema(parsed, recommendation_schema)
    if not errors:
        print("✅ Schema validation passed")
        print("Recommendation:")
        print(json.dumps(parsed, indent=2))
    else:
        print(f"❌ Schema validation failed:")
        for err in errors:
            print(f"  - {err}")

# %% [markdown]
# ## Step 7 — Retry with Error Feedback
#
# If validation failed, send the errors back to the LLM and ask it to fix the recommendation. This demonstrates how structured outputs work with retries: the LLM sees exactly what's wrong and can correct it.

# %%
async def extract_recommendation_with_retry(brief, schema, max_retries=2):
    """Extract a structured recommendation with retry on validation failure."""
    system_prompt = f"""You are a management consultant. Analyze the consulting brief and produce a JSON recommendation.
    Your response MUST be valid JSON matching this schema:
    {json.dumps(schema)}
    
    Respond ONLY with the JSON object, no markdown or extra text."""
    
    for attempt in range(max_retries):
        if attempt == 0:
            # First attempt: just the brief
            msg = brief
        else:
            # Retry: brief + validation errors
            msg = f"{brief}\n\nPrevious attempt had these errors:\n" + "\n".join([f"  - {e}" for e in errors])
        
        r = await lrn_llm.call(
            [{"role": "user", "content": msg}],
            system=system_prompt,
            max_tokens=300
        )
        raw = lrn_llm.text(r)
        
        try:
            parsed = json.loads(raw)
        except json.JSONDecodeError as e:
            print(f"  Attempt {attempt + 1}: JSON parse error -- {e}")
            continue
        
        errors = validate_schema(parsed, schema)
        if not errors:
            print(f"  Attempt {attempt + 1}: ✅ Success")
            return parsed
        
        print(f"  Attempt {attempt + 1}: Validation failed -- {errors}")
    
    return None

print("Extracting recommendation with retry...")
result = await extract_recommendation_with_retry(consulting_brief, recommendation_schema, max_retries=2)
if result:
    print("\nFinal recommendation:")
    print(json.dumps(result, indent=2))
else:
    print("❌ Failed to extract valid recommendation after retries")

